#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Lencana level bergambar + naik level lebih sulit setelah Level 10
#  - Gambar lencana per tier level (res/drawable-nodpi/bg_level_*) tampil di Profil & halaman Level
#  - Level 1-10 sama seperti sebelumnya; mulai Level 11 butuh jauh lebih banyak EXP
#  - Tier 100-119 & 180-199 belum ada gambarnya: sementara pakai tier di bawahnya.
#    Tambah file bg_level_100_119.webp / bg_level_180_199.webp ke res/drawable-nodpi, otomatis terpakai.
# Jalankan di root repo:  bash pasang-level.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
[ -f "$D/LevelActivity.kt" ] || { echo "❌ Jalankan di root repo Hayu-android"; exit 1; }
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"
BK="$HOME/.hayu-backup-level-$(date +%H%M%S)"
N=0
for f in $(cd "$T/new" && find . -type f | sed 's#^\./##'); do
  [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
  mkdir -p "$(dirname "$f")"
  cp "$T/new/$f" "$f"
  echo "  dipasang $f"
  N=$((N+1))
done
rm -rf "$T"

# --- Ui.kt: arahkan rumus level ke kurva baru ---
U="$D/Ui.kt"
if grep -q "LevelCurve" "$U"; then
  echo "  ok         $U"
else
  mkdir -p "$BK/$D"; cp "$U" "$BK/$U"
  sed -i 's#fun levelForExp(exp: Int): Int = sqrt(exp / 50.0).toInt() + 1#fun levelForExp(exp: Int): Int = LevelCurve.levelForExp(exp)#' "$U"
  sed -i 's#fun expForLevel(level: Int): Int = 50 \* (level - 1) \* (level - 1)#fun expForLevel(level: Int): Int = LevelCurve.expForLevel(level)#' "$U"
  grep -q "LevelCurve.levelForExp" "$U" && grep -q "LevelCurve.expForLevel" "$U" || { echo "❌ Gagal mengubah $U (rumus level tidak ditemukan)"; exit 1; }
  echo "  DIPERBAIKI $U"
fi

# --- ProfileFragment.kt: level dari EXP + lencana bergambar ---
P="$D/ProfileFragment.kt"
if grep -q "LevelBadge.style" "$P"; then
  echo "  ok         $P"
else
  mkdir -p "$BK/$D"; cp "$P" "$BK/$P"
  sed -i 's#^\( *\)val level = (doc.getLong("level") ?: 1L).toInt()$#\1val level = LevelCurve.levelForExp((doc.getLong("exp") ?: 0L).coerceIn(0L, Int.MAX_VALUE.toLong()).toInt())\n\1if ((doc.getLong("level") ?: 1L).toInt() != level) doc.reference.update("level", level.toLong())#' "$P"
  sed -i 's#tvLevelBadge.text = "Lv. \$level"#LevelBadge.style(tvLevelBadge, level)#' "$P"
  grep -q "LevelBadge.style" "$P" && grep -q "LevelCurve.levelForExp" "$P" || { echo "❌ Gagal mengubah $P (baris level tidak ditemukan)"; exit 1; }
  echo "  DIPERBAIKI $P"
fi
echo "✅ Selesai. Backup: $BK"
echo "Lanjut: git add -A && git commit -m 'lencana level + level lebih sulit' && git push"
